-- Generated by: cd backend && python -m scripts.export_schema

-- Source of truth: app.models.Base.metadata. Intended for an empty SQLite database.

PRAGMA foreign_keys = ON;

BEGIN TRANSACTION;

CREATE TABLE app_user (
    user_id INTEGER NOT NULL,
    email VARCHAR(254) NOT NULL,
    display_name VARCHAR(100) NOT NULL,
    role VARCHAR(20) DEFAULT 'fan' NOT NULL,
    CONSTRAINT pk_app_user PRIMARY KEY (user_id),
    CONSTRAINT ck_app_user_nonblank_fields CHECK (length(trim(email)) > 0 AND length(trim(display_name)) > 0),
    CONSTRAINT ck_app_user_valid_role CHECK (role IN ('fan', 'analyst', 'admin')),
    CONSTRAINT uq_app_user_email UNIQUE (email)
);

CREATE TABLE athlete (
    athlete_id INTEGER NOT NULL,
    first_name VARCHAR(100) NOT NULL,
    last_name VARCHAR(100) NOT NULL,
    nationality VARCHAR(100),
    CONSTRAINT pk_athlete PRIMARY KEY (athlete_id),
    CONSTRAINT ck_athlete_nonblank_fields CHECK (length(trim(first_name)) > 0 AND length(trim(last_name)) > 0)
);

CREATE INDEX ix_athlete_last_name ON athlete (last_name);

CREATE TABLE sport (
    sport_id INTEGER NOT NULL,
    sport_name VARCHAR(100) NOT NULL,
    CONSTRAINT pk_sport PRIMARY KEY (sport_id),
    CONSTRAINT ck_sport_nonblank_fields CHECK (length(trim(sport_name)) > 0),
    CONSTRAINT uq_sport_sport_name UNIQUE (sport_name)
);

CREATE TABLE venue (
    venue_id INTEGER NOT NULL,
    venue_name VARCHAR(150) NOT NULL,
    city VARCHAR(100) NOT NULL,
    CONSTRAINT pk_venue PRIMARY KEY (venue_id),
    CONSTRAINT ck_venue_nonblank_fields CHECK (length(trim(venue_name)) > 0 AND length(trim(city)) > 0)
);

CREATE TABLE data_import (
    import_id INTEGER NOT NULL,
    source_name VARCHAR(200) NOT NULL,
    imported_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL,
    status VARCHAR(20) DEFAULT 'pending' NOT NULL,
    run_by_user_id INTEGER,
    CONSTRAINT pk_data_import PRIMARY KEY (import_id),
    CONSTRAINT ck_data_import_nonblank_fields CHECK (length(trim(source_name)) > 0),
    CONSTRAINT ck_data_import_valid_status CHECK (status IN ('completed', 'failed', 'pending')),
    CONSTRAINT fk_data_import_run_by_user_id_app_user FOREIGN KEY(run_by_user_id) REFERENCES app_user (user_id) ON DELETE SET NULL
);

CREATE INDEX ix_data_import_run_by_user_id ON data_import (run_by_user_id);

CREATE TABLE league (
    league_id INTEGER NOT NULL,
    league_name VARCHAR(150) NOT NULL,
    country VARCHAR(100) NOT NULL,
    sport_id INTEGER NOT NULL,
    CONSTRAINT pk_league PRIMARY KEY (league_id),
    CONSTRAINT ck_league_nonblank_fields CHECK (length(trim(league_name)) > 0 AND length(trim(country)) > 0),
    CONSTRAINT fk_league_sport_id_sport FOREIGN KEY(sport_id) REFERENCES sport (sport_id) ON DELETE RESTRICT,
    CONSTRAINT uq_league_sport_id UNIQUE (sport_id, league_name)
);

CREATE INDEX ix_league_sport_id ON league (sport_id);

CREATE TABLE stat_definition (
    stat_definition_id INTEGER NOT NULL,
    stat_name VARCHAR(100) NOT NULL,
    abbreviation VARCHAR(20) NOT NULL,
    calc_type VARCHAR(20) NOT NULL,
    sport_id INTEGER NOT NULL,
    CONSTRAINT pk_stat_definition PRIMARY KEY (stat_definition_id),
    CONSTRAINT ck_stat_definition_nonblank_fields CHECK (length(trim(stat_name)) > 0 AND length(trim(abbreviation)) > 0),
    CONSTRAINT ck_stat_definition_valid_calc_type CHECK (calc_type IN ('sum', 'average', 'min', 'max', 'last')),
    CONSTRAINT fk_stat_definition_sport_id_sport FOREIGN KEY(sport_id) REFERENCES sport (sport_id) ON DELETE RESTRICT,
    CONSTRAINT uq_stat_definition_sport_id UNIQUE (sport_id, abbreviation)
);

CREATE INDEX ix_stat_definition_sport_id ON stat_definition (sport_id);

CREATE TABLE season (
    season_id INTEGER NOT NULL,
    season_name VARCHAR(100) NOT NULL,
    start_date DATE NOT NULL,
    end_date DATE NOT NULL,
    league_id INTEGER NOT NULL,
    CONSTRAINT pk_season PRIMARY KEY (season_id),
    CONSTRAINT ck_season_date_order CHECK (end_date >= start_date),
    CONSTRAINT ck_season_nonblank_fields CHECK (length(trim(season_name)) > 0),
    CONSTRAINT fk_season_league_id_league FOREIGN KEY(league_id) REFERENCES league (league_id) ON DELETE RESTRICT,
    CONSTRAINT uq_season_league_id UNIQUE (league_id, season_name)
);

CREATE INDEX ix_season_league_id ON season (league_id);

CREATE TABLE team (
    team_id INTEGER NOT NULL,
    team_name VARCHAR(150) NOT NULL,
    city VARCHAR(100) NOT NULL,
    league_id INTEGER NOT NULL,
    CONSTRAINT pk_team PRIMARY KEY (team_id),
    CONSTRAINT ck_team_nonblank_fields CHECK (length(trim(team_name)) > 0 AND length(trim(city)) > 0),
    CONSTRAINT fk_team_league_id_league FOREIGN KEY(league_id) REFERENCES league (league_id) ON DELETE RESTRICT,
    CONSTRAINT uq_team_league_id UNIQUE (league_id, team_name)
);

CREATE INDEX ix_team_league_id ON team (league_id);

CREATE TABLE favorite (
    favorite_id INTEGER NOT NULL,
    user_id INTEGER NOT NULL,
    sport_id INTEGER,
    league_id INTEGER,
    team_id INTEGER,
    athlete_id INTEGER,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT pk_favorite PRIMARY KEY (favorite_id),
    CONSTRAINT ck_favorite_one_target CHECK (CASE WHEN sport_id IS NOT NULL THEN 1 ELSE 0 END + CASE WHEN league_id IS NOT NULL THEN 1 ELSE 0 END + CASE WHEN team_id IS NOT NULL THEN 1 ELSE 0 END + CASE WHEN athlete_id IS NOT NULL THEN 1 ELSE 0 END = 1),
    CONSTRAINT fk_favorite_athlete_id_athlete FOREIGN KEY(athlete_id) REFERENCES athlete (athlete_id) ON DELETE CASCADE,
    CONSTRAINT fk_favorite_league_id_league FOREIGN KEY(league_id) REFERENCES league (league_id) ON DELETE CASCADE,
    CONSTRAINT fk_favorite_sport_id_sport FOREIGN KEY(sport_id) REFERENCES sport (sport_id) ON DELETE CASCADE,
    CONSTRAINT fk_favorite_team_id_team FOREIGN KEY(team_id) REFERENCES team (team_id) ON DELETE CASCADE,
    CONSTRAINT fk_favorite_user_id_app_user FOREIGN KEY(user_id) REFERENCES app_user (user_id) ON DELETE CASCADE,
    CONSTRAINT uq_favorite_athlete UNIQUE (user_id, athlete_id),
    CONSTRAINT uq_favorite_league UNIQUE (user_id, league_id),
    CONSTRAINT uq_favorite_sport UNIQUE (user_id, sport_id),
    CONSTRAINT uq_favorite_team UNIQUE (user_id, team_id)
);

CREATE INDEX ix_favorite_athlete_id ON favorite (athlete_id);

CREATE INDEX ix_favorite_league_id ON favorite (league_id);

CREATE INDEX ix_favorite_sport_id ON favorite (sport_id);

CREATE INDEX ix_favorite_team_id ON favorite (team_id);

CREATE INDEX ix_favorite_user_id ON favorite (user_id);

CREATE TABLE game (
    game_id INTEGER NOT NULL,
    game_time DATETIME NOT NULL,
    status VARCHAR(20) DEFAULT 'scheduled' NOT NULL,
    season_id INTEGER NOT NULL,
    venue_id INTEGER,
    CONSTRAINT pk_game PRIMARY KEY (game_id),
    CONSTRAINT ck_game_valid_status CHECK (status IN ('scheduled', 'in_progress', 'completed', 'cancelled')),
    CONSTRAINT fk_game_season_id_season FOREIGN KEY(season_id) REFERENCES season (season_id) ON DELETE RESTRICT,
    CONSTRAINT fk_game_venue_id_venue FOREIGN KEY(venue_id) REFERENCES venue (venue_id) ON DELETE SET NULL
);

CREATE INDEX ix_game_game_time ON game (game_time);

CREATE INDEX ix_game_season_id ON game (season_id);

CREATE INDEX ix_game_venue_id ON game (venue_id);

CREATE TABLE roster (
    roster_id INTEGER NOT NULL,
    team_id INTEGER NOT NULL,
    season_id INTEGER NOT NULL,
    CONSTRAINT pk_roster PRIMARY KEY (roster_id),
    CONSTRAINT fk_roster_season_id_season FOREIGN KEY(season_id) REFERENCES season (season_id) ON DELETE RESTRICT,
    CONSTRAINT fk_roster_team_id_team FOREIGN KEY(team_id) REFERENCES team (team_id) ON DELETE RESTRICT,
    CONSTRAINT uq_roster_team_id UNIQUE (team_id, season_id)
);

CREATE INDEX ix_roster_season_id ON roster (season_id);

CREATE INDEX ix_roster_team_id ON roster (team_id);

CREATE TABLE saved_comparison (
    comparison_id INTEGER NOT NULL,
    user_id INTEGER NOT NULL,
    sport_id INTEGER NOT NULL,
    object_type VARCHAR(20) NOT NULL,
    athlete_a_id INTEGER,
    athlete_b_id INTEGER,
    team_a_id INTEGER,
    team_b_id INTEGER,
    title VARCHAR(200) NOT NULL,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT pk_saved_comparison PRIMARY KEY (comparison_id),
    CONSTRAINT ck_saved_comparison_nonblank_fields CHECK (length(trim(title)) > 0),
    CONSTRAINT ck_saved_comparison_valid_pair CHECK ((object_type = 'athlete' AND athlete_a_id IS NOT NULL AND athlete_b_id IS NOT NULL AND athlete_a_id <> athlete_b_id AND team_a_id IS NULL AND team_b_id IS NULL) OR (object_type = 'team' AND team_a_id IS NOT NULL AND team_b_id IS NOT NULL AND team_a_id <> team_b_id AND athlete_a_id IS NULL AND athlete_b_id IS NULL)),
    CONSTRAINT fk_saved_comparison_athlete_a_id_athlete FOREIGN KEY(athlete_a_id) REFERENCES athlete (athlete_id) ON DELETE CASCADE,
    CONSTRAINT fk_saved_comparison_athlete_b_id_athlete FOREIGN KEY(athlete_b_id) REFERENCES athlete (athlete_id) ON DELETE CASCADE,
    CONSTRAINT fk_saved_comparison_sport_id_sport FOREIGN KEY(sport_id) REFERENCES sport (sport_id) ON DELETE CASCADE,
    CONSTRAINT fk_saved_comparison_team_a_id_team FOREIGN KEY(team_a_id) REFERENCES team (team_id) ON DELETE CASCADE,
    CONSTRAINT fk_saved_comparison_team_b_id_team FOREIGN KEY(team_b_id) REFERENCES team (team_id) ON DELETE CASCADE,
    CONSTRAINT fk_saved_comparison_user_id_app_user FOREIGN KEY(user_id) REFERENCES app_user (user_id) ON DELETE CASCADE
);

CREATE INDEX ix_saved_comparison_athlete_a_id ON saved_comparison (athlete_a_id);

CREATE INDEX ix_saved_comparison_athlete_b_id ON saved_comparison (athlete_b_id);

CREATE INDEX ix_saved_comparison_sport_id ON saved_comparison (sport_id);

CREATE INDEX ix_saved_comparison_team_a_id ON saved_comparison (team_a_id);

CREATE INDEX ix_saved_comparison_team_b_id ON saved_comparison (team_b_id);

CREATE INDEX ix_saved_comparison_user_id ON saved_comparison (user_id);

CREATE TABLE standing (
    standing_id INTEGER NOT NULL,
    team_id INTEGER NOT NULL,
    season_id INTEGER NOT NULL,
    rank INTEGER NOT NULL,
    wins INTEGER DEFAULT '0' NOT NULL,
    losses INTEGER DEFAULT '0' NOT NULL,
    ties INTEGER DEFAULT '0' NOT NULL,
    points FLOAT DEFAULT '0' NOT NULL,
    CONSTRAINT pk_standing PRIMARY KEY (standing_id),
    CONSTRAINT ck_standing_nonnegative_points CHECK (points >= 0),
    CONSTRAINT ck_standing_nonnegative_record CHECK (wins >= 0 AND losses >= 0 AND ties >= 0),
    CONSTRAINT ck_standing_positive_rank CHECK (rank > 0),
    CONSTRAINT fk_standing_season_id_season FOREIGN KEY(season_id) REFERENCES season (season_id) ON DELETE CASCADE,
    CONSTRAINT fk_standing_team_id_team FOREIGN KEY(team_id) REFERENCES team (team_id) ON DELETE CASCADE,
    CONSTRAINT uq_standing_team_id UNIQUE (team_id, season_id)
);

CREATE INDEX ix_standing_season_id ON standing (season_id);

CREATE INDEX ix_standing_team_id ON standing (team_id);

CREATE TABLE game_participant (
    game_id INTEGER NOT NULL,
    team_id INTEGER NOT NULL,
    participant_role VARCHAR(10) NOT NULL,
    score INTEGER,
    CONSTRAINT pk_game_participant PRIMARY KEY (game_id, team_id),
    CONSTRAINT ck_game_participant_nonnegative_score CHECK (score IS NULL OR score >= 0),
    CONSTRAINT ck_game_participant_valid_role CHECK (participant_role IN ('home', 'away')),
    CONSTRAINT fk_game_participant_game_id_game FOREIGN KEY(game_id) REFERENCES game (game_id) ON DELETE CASCADE,
    CONSTRAINT fk_game_participant_team_id_team FOREIGN KEY(team_id) REFERENCES team (team_id) ON DELETE RESTRICT,
    CONSTRAINT uq_game_participant_game_id UNIQUE (game_id, participant_role)
);

CREATE INDEX ix_game_participant_team_id ON game_participant (team_id);

CREATE TABLE membership (
    membership_id INTEGER NOT NULL,
    roster_id INTEGER NOT NULL,
    athlete_id INTEGER NOT NULL,
    position VARCHAR(40) NOT NULL,
    jersey_number VARCHAR(10),
    start_date DATE NOT NULL,
    end_date DATE,
    CONSTRAINT pk_membership PRIMARY KEY (membership_id),
    CONSTRAINT ck_membership_date_order CHECK (end_date IS NULL OR end_date >= start_date),
    CONSTRAINT ck_membership_nonblank_fields CHECK (length(trim(position)) > 0),
    CONSTRAINT fk_membership_athlete_id_athlete FOREIGN KEY(athlete_id) REFERENCES athlete (athlete_id) ON DELETE RESTRICT,
    CONSTRAINT fk_membership_roster_id_roster FOREIGN KEY(roster_id) REFERENCES roster (roster_id) ON DELETE CASCADE,
    CONSTRAINT uq_membership_roster_id UNIQUE (roster_id, athlete_id, start_date)
);

CREATE INDEX ix_membership_athlete_id ON membership (athlete_id);

CREATE INDEX ix_membership_roster_id ON membership (roster_id);

CREATE TABLE performance_statistic (
    performance_statistic_id INTEGER NOT NULL,
    game_id INTEGER NOT NULL,
    stat_definition_id INTEGER NOT NULL,
    athlete_id INTEGER,
    team_id INTEGER,
    stat_value FLOAT NOT NULL,
    CONSTRAINT pk_performance_statistic PRIMARY KEY (performance_statistic_id),
    CONSTRAINT ck_performance_statistic_one_subject CHECK ((athlete_id IS NOT NULL AND team_id IS NULL) OR (athlete_id IS NULL AND team_id IS NOT NULL)),
    CONSTRAINT fk_performance_statistic_athlete_id_athlete FOREIGN KEY(athlete_id) REFERENCES athlete (athlete_id) ON DELETE RESTRICT,
    CONSTRAINT fk_performance_statistic_game_id_game FOREIGN KEY(game_id) REFERENCES game (game_id) ON DELETE CASCADE,
    CONSTRAINT fk_performance_statistic_stat_definition_id_stat_definition FOREIGN KEY(stat_definition_id) REFERENCES stat_definition (stat_definition_id) ON DELETE RESTRICT,
    CONSTRAINT fk_performance_statistic_team_id_team FOREIGN KEY(team_id) REFERENCES team (team_id) ON DELETE RESTRICT,
    CONSTRAINT uq_performance_statistic_athlete UNIQUE (game_id, stat_definition_id, athlete_id),
    CONSTRAINT uq_performance_statistic_team UNIQUE (game_id, stat_definition_id, team_id)
);

CREATE INDEX ix_performance_statistic_athlete_id ON performance_statistic (athlete_id);

CREATE INDEX ix_performance_statistic_game_id ON performance_statistic (game_id);

CREATE INDEX ix_performance_statistic_stat_definition_id ON performance_statistic (stat_definition_id);

CREATE INDEX ix_performance_statistic_team_id ON performance_statistic (team_id);

COMMIT;
